#pragma once
// Buffered output driver for EmbAJAX on the ESP32 WebServer.
//
// The stock driver calls sendContent() for every tiny fragment, and each call on a
// chunked reply costs three TCP writes (~2 ms each). This subclass collects the output
// and sends it in ~1.4 KB chunks instead. The EmbAJAX library itself is not modified.
// Generated by Claude Sonnet 5.5 on the 24/11/26
#include <EmbAJAX.h>  // also pulls in the ESP32 driver (EmbAJAXOutputDriverGeneric)
#include <string.h>

class BufferedOutputDriver : public EmbAJAXOutputDriverGeneric {
public:
  explicit BufferedOutputDriver(EmbAJAXOutputDriverWebServerClass* server)
    : EmbAJAXOutputDriverGeneric(server), _srv(server), _len(0) {}

  void printHeader(bool html) override {
    _len = 0;  // new response: drop anything left over
    EmbAJAXOutputDriverGeneric::printHeader(html);
  }

  void printContent(const char* content) override {
    size_t n = strlen(content);
    while (n > 0) {
      size_t space = OUT_BUF_SIZE - _len;
      size_t part = (n < space) ? n : space;
      memcpy(_buf + _len, content, part);
      _len += part;
      content += part;
      n -= part;
      if (_len >= OUT_BUF_SIZE) flushOutput();
    }
  }

  void installPage(EmbAJAXPageBase* page, const char* path, void (*change_callback)() = 0) override {
    _srv->on(path, [this, page, change_callback]() {
      if (_srv->method() == HTTP_POST) {  // AJAX request
        page->handleRequest(change_callback);
      } else {  // page load
        page->printPage();
      }
      flushOutput();  // send the remainder before the server closes the chunked reply
    });
  }

private:
  // Just under the TCP segment size (MSS 1436 on the ESP32), leaving room for chunk framing.
  static constexpr size_t OUT_BUF_SIZE = 1400;

  void flushOutput() {
    if (_len == 0) return;
    _buf[_len] = '\0';
    _srv->sendContent(_buf);
    _len = 0;
  }

  EmbAJAXOutputDriverWebServerClass* _srv;
  char _buf[OUT_BUF_SIZE + 1];
  size_t _len;
};